 "developpeurs.h2.une-suite-defi-et-dex-native": "A native DeFi and DEX suite.",
 "developpeurs.h3.ce-que-brc20-ajoute": "What BRC20 adds",
 "developpeurs.h3.ce-qui-identifie-la-chaine": "What identifies the chain",
 "developpeurs.h3.creer-des-pools-de-liquidite": "Creating liquidity pools",
 "developpeurs.h3.deployer-des-jetons-sans-restriction": "Deploying tokens without restriction",
